class ManufacturingCheckResult(TypedDict):
    """CAD manufacturing-intent check result (result.json of a bundle.checks bundle)

    One producer's required-check packet for one version: the obligations it was asked to cover (manufacturing_intent.required_checks, enumerated before it ran), one outcome per obligation, its findings, the dependency fingerprints it read and whether it covered every expected obligation. A producer cannot shrink its scope by omission: an expected obligation without an outcome makes the packet incomplete, and unknown never counts as pass

    Source: skills/cad-record/schemas/manufacturing-check-result.schema.json#

    Not expressible as types (see the schema):
    - additionalProperties: false

    Field notes:
    - producer: the writing tool and its version
    - scope: minItems: 1
    - dependencies: sha256 of each input the producer read, by name, such as the part record, material and capability profiles and the geometry; propertyNames: {"$ref":"manufacturing.schema.json#/$defs/semantic_id"}
    - complete: true only when every expected obligation has an outcome
    - result: fail if any outcome fails, else unknown if any is unknown or the packet is incomplete, else not_assessed if any outcome is, else pass (not_applicable outcomes aside)
    """
    schema_version: Required[Literal[1]]
    record_version: Required[ManufacturingRecordVersion]
    producer: Required[ManufacturingText]
    scope: Required[list[ManufacturingSubject]]
    expected: Required[list[ManufacturingObligation]]
    outcomes: Required[list[ManufacturingObligationOutcome]]
    findings: Required[list[ManufacturingFinding]]
    dependencies: Required[Mapping[str, ManufacturingSha256]]
    complete: Required[bool]
    result: Required[ManufacturingOutcome]


